function nextId(a){return a.reduce(function(m,x){return Math.max(m,Number(x.id)||0)},0)+1}

async function loadData(){if(state.demo){demoLoad()}else{var all=await Promise.all([grist.docApi.fetchTable(TABLES.projects),grist.docApi.fetchTable(TABLES.tasks),grist.docApi.fetchTable(TABLES.time),grist.docApi.fetchTable(TABLES.settings),grist.docApi.fetchTable(TABLES.files),grist.docApi.fetchTable(TABLES.links),grist.docApi.fetchTable(TABLES.checklist),grist.docApi.fetchTable(TABLES.journal)]);state.projects=records(all[0],projectMap());state.tasks=records(all[1],taskMap());state.time=records(all[2],timeMap());var settings=records(all[3],settingMap()),last=settings.find(function(x){return x.Key==='last_sync'});state.lastSync=last&&last.Value?Number(last.Value):null;state.files=records(all[4],fileMap());state.links=records(all[5],linkMap());state.checklist=records(all[6],checklistMap());state.journal=records(all[7],journalMap())}refresh()}
async function saveLastSync(value){var data=await grist.docApi.fetchTable(TABLES.settings),settings=records(data,settingMap()),record=settings.find(function(x){return x.Key==='last_sync'});if(record)await grist.docApi.applyUserActions([['UpdateRecord',TABLES.settings,Number(record.id),{Value:String(value)}]]);else await grist.docApi.applyUserActions([['AddRecord',TABLES.settings,null,{Key:'last_sync',Value:String(value)}]]);state.lastSync=value}
async function addRecord(table,fields){if(state.demo){var list=table===TABLES.projects?state.projects:table===TABLES.tasks?state.tasks:state.time;var rec=Object.assign({id:nextId(list)},fields);list.push(rec);demoSave();return rec.id}var r=await grist.docApi.applyUserActions([['AddRecord',table,null,fields]]);return r&&r.retValues?r.retValues[0]:r}
