async function removeRecord(table,id){if(state.demo){var key=table===TABLES.projects?'projects':table===TABLES.tasks?'tasks':'time';state[key]=state[key].filter(function(x){return String(x.id)!==String(id)});demoSave()}else{if(table===TABLES.tasks||table===TABLES.projects){var type=table===TABLES.tasks?'task':'project',actions=[];state.files.concat(state.links,state.journal).filter(function(x){return x.Parent_Type===type&&String(x.Parent_Id)===String(id)}).forEach(function(x){var source=state.files.indexOf(x)!==-1?TABLES.files:state.links.indexOf(x)!==-1?TABLES.links:TABLES.journal;actions.push(['RemoveRecord',source,Number(x.id)])});if(type==='task')state.checklist.filter(function(x){return String(x.Task_Id)===String(id)}).forEach(function(x){actions.push(['RemoveRecord',TABLES.checklist,Number(x.id)])});if(actions.length)await grist.docApi.applyUserActions(actions)}await grist.docApi.applyUserActions([['RemoveRecord',table,Number(id)]])}}

function normKey(v){return String(v||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]/g,'')}
function sourceColumn(data,candidates){var keys=Object.keys(data||{}),wanted=candidates.map(normKey);for(var i=0;i<keys.length;i++){var n=normKey(keys[i]);if(wanted.indexOf(n)!==-1)return keys[i]}for(var j=0;j<keys.length;j++){var nk=normKey(keys[j]);if(wanted.some(function(w){return nk.indexOf(w)!==-1||w.indexOf(nk)!==-1}))return keys[j]}return null}
function importedStatus(v){var n=normKey(v);if(n.indexOf('final')!==-1||n.indexOf('termine')!==-1)return'done';if(n.indexOf('annul')!==-1||n.indexOf('horsimc')!==-1)return'cancelled';if(n.indexOf('encours')!==-1)return'active';if(n.indexOf('attente')!==-1||n.indexOf('arbitrage')!==-1)return'waiting';return'planned'}
function importedPriority(v){var n=normKey(v);return n.indexOf('haute')!==-1?'high':n.indexOf('basse')!==-1?'low':'medium'}
function cleanImportedDate(v){if(!v)return null;var d=day(v);if(!d&&typeof v==='string')d=new Date(v);if(!d||isNaN(d)||d.getFullYear()>2100||d.getFullYear()<2000)return null;return typeof v==='number'?v:Math.floor(d.getTime()/1000)}
function importedDuplicateIds(){var seen={};return state.projects.filter(function(p){if(!p.Source_Table||!p.Source_Record_Id)return false;var key=p.Source_Table+'|'+p.Source_Record_Id;if(seen[key])return true;seen[key]=true;return false}).map(function(p){return p.id})}
function requestSourceKey(v){if(v==null||v==='')return null;if(typeof v==='number')return Math.round(v);var d=new Date(v);return isNaN(d)?null:Math.round(d.getTime()/1000)}
async function importExistingProjects(){
  if(state.demo){toast('L’import fonctionne uniquement dans votre document Grist');return}
  if(state.importing)return;
  var duplicates=importedDuplicateIds();
  if(duplicates.length){
    if(!confirm('Supprimer '+duplicates.length+' doublon(s) créé(s) lors de l’import précédent ?'))return;
    state.importing=true;updateImportButton();
    try{for(var d=0;d<duplicates.length;d++)await removeRecord(TABLES.projects,duplicates[d]);await loadData();toast(duplicates.length+' doublon(s) supprimé(s).')}finally{state.importing=false;updateImportButton()}
    return;
  }
  state.importing=true;updateImportButton();
  try{
    var data;try{data=await grist.docApi.fetchTable('Table_demande_IMC')}catch(e){toast('Table « Table_demande_IMC » introuvable.');return}
    var cols={selected:sourceColumn(data,['A_integrer_pilotage']),created:sourceColumn(data,['Créé le - à','Cree le a']),name:sourceColumn(data,['Titre du projet']),status:sourceColumn(data,['Statut']),priority:sourceColumn(data,['Importance','Urgence']),due:sourceColumn(data,["Date de l'action",'AFF_Date']),notes:sourceColumn(data,['Informations complémentaires','Objectif de action']),type:sourceColumn(data,['Dans quel domaine sollicitez-vous un accompagnement','AFF_Domaine_accompagnement']),risks:sourceColumn(data,['Points de vigilance'])};
    if(!cols.selected||!cols.created||!cols.name){toast('Colonnes A_integrer_pilotage, Créé le - à ou Titre du projet introuvables.');return}
    var existing={},oldByName={};state.projects.forEach(function(p){if(p.Source_Table==='Table_demande_IMC'&&p.Source_Record_Id)existing[p.Source_Record_Id]=p;if(p.Source_Table==='Projet_innovants')oldByName[normKey(p.Name)]=(oldByName[normKey(p.Name)]||[]).concat([p])});
    var added=0,updated=0,unchanged=0,migrated=0,selectedCount=0;
    for(var i=0;i<data.id.length;i++){
      if(!data[cols.selected]||!data[cols.selected][i])continue;selectedCount++;
      var name=data[cols.name]&&data[cols.name][i];if(!name)continue;
      var key=requestSourceKey(data[cols.created]&&data[cols.created][i]);if(!key){toast('Date de création invalide pour « '+String(name)+' ». Synchronisation interrompue.');return}
      var sourceFields={Name:String(name).trim(),Type:cols.type&&data[cols.type]?String(data[cols.type][i]||''):'',Status:importedStatus(cols.status&&data[cols.status]?data[cols.status][i]:''),Due_Date:cleanImportedDate(cols.due&&data[cols.due]?data[cols.due][i]:null)},current=existing[key];
      if(!current){var matches=oldByName[normKey(name)]||[];if(matches.length===1){current=matches[0];await updateRecord(TABLES.projects,current.id,{Source_Table:'Table_demande_IMC',Source_Record_Id:key,Updated_At:now()});current.Source_Table='Table_demande_IMC';current.Source_Record_Id=key;existing[key]=current;migrated++}}
      if(!current){await addRecord(TABLES.projects,Object.assign({},sourceFields,{Priority:importedPriority(cols.priority&&data[cols.priority]?data[cols.priority][i]:''),Next_Action:cols.notes&&data[cols.notes]?String(data[cols.notes][i]||''):'',Risks:cols.risks&&data[cols.risks]?String(data[cols.risks][i]||''):'',Start_Date:null,Progress:0,Decision:'',Review:false,Source_Table:'Table_demande_IMC',Source_Record_Id:key,Created_At:now(),Updated_At:now()}));added++;continue}
      var changes={};Object.keys(sourceFields).forEach(function(k){if(String(current[k]==null?'':current[k])!==String(sourceFields[k]==null?'':sourceFields[k]))changes[k]=sourceFields[k]});
      if(Object.keys(changes).length){changes.Updated_At=now();await updateRecord(TABLES.projects,current.id,changes);updated++}else unchanged++;
    }
    await saveLastSync(Date.now());await loadData();toast(selectedCount+' sélectionnée(s) : '+added+' ajoutée(s), '+migrated+' reliée(s), '+updated+' actualisée(s), '+unchanged+' inchangée(s).');
  }finally{state.importing=false;updateImportButton()}
}
function updateImportButton(){var b=$('import-projects');if(!b)return;var duplicates=importedDuplicateIds().length,last=state.lastSync;b.disabled=state.importing;b.textContent=state.importing?'Synchronisation…':duplicates?'Nettoyer '+duplicates+' doublon(s)':'Synchroniser les demandes sélectionnées';if($('sync-status'))$('sync-status').textContent=last?'Dernière synchronisation : '+new Date(Number(last)).toLocaleString('fr-FR'):'Aucune synchronisation enregistrée'}

function filteredTasks(){return state.tasks.filter(function(t){if(state.project&&String(t.Project_Id)!==String(state.project))return false;if(!state.showDone&&isDone(t.Status))return false;return true})}
function timeForTask(id,year){return state.time.filter(function(x){return String(x.Task_Id)===String(id)&&x.End_Time&&(!year||new Date(x.End_Time*1000).getFullYear()===year)}).reduce(function(s,x){return s+(Number(x.Duration)||0)},0)}
function timeForProject(id,year){return state.tasks.filter(function(t){return String(t.Project_Id)===String(id)}).reduce(function(s,t){return s+timeForTask(t.id,year)},0)}
function activeEntry(){return state.time.find(function(x){return !x.End_Time})}

function refreshSelectors(){var p=$('project-filter'),v=p.value;p.innerHTML='<option value="">Tous les projets</option>'+state.projects.slice().sort(function(a,b){return a.Name.localeCompare(b.Name)}).map(function(x){return '<option value="'+x.id+'">'+esc(x.Name)+'</option>'}).join('');p.value=state.project||v||'';var tp=$('task-project'),tv=tp.value;tp.innerHTML='<option value="">Sans projet</option>'+state.projects.map(function(x){return '<option value="'+x.id+'">'+esc(x.Name)+'</option>'}).join('');tp.value=tv;var yf=$('year-filter');if(!yf.options.length){var y=new Date().getFullYear(),html='';for(var i=y-3;i<=y+2;i++)html+='<option value="'+i+'">'+i+'</option>';yf.innerHTML=html;yf.value=state.year}}
function refresh(){refreshSelectors();updateImportButton();renderDashboard();renderKanban();renderCalendar();renderGantt();renderReview();renderReport();renderRunning()}

function renderDashboard(){var y=state.year,tasks=state.tasks.filter(function(t){return !state.project||String(t.Project_Id)===String(state.project)}),doneY=tasks.filter(function(t){return t.Completed_At&&new Date(t.Completed_At*1000).getFullYear()===y}),active=tasks.filter(function(t){return !isDone(t.Status)}),today=new Date(new Date().setHours(0,0,0,0)),over=active.filter(function(t){var d=day(t.Due_Date);return d&&d<today}),sec=tasks.reduce(function(s,t){return s+timeForTask(t.id,y)},0),projects=state.projects.filter(function(p){return (!state.project||String(p.id)===String(state.project))&&!isDone(p.Status)});$('metrics').innerHTML=metric('Projets actifs',projects.length,'En cours ou à préparer',true)+metric('Tâches ouvertes',active.length,'À organiser et réaliser',true)+metric('Terminées en '+y,doneY.length,'Trace de l’activité',true)+metric('En retard',over.length,'À replanifier ou terminer',true)+metric('Temps suivi',duration(sec),'Ouvrir le bilan annuel',true);var soon=active.filter(function(t){var d=day(t.Due_Date);if(!d)return false;return (d-today)/864e5<=14}).sort(function(a,b){return (a.Due_Date||9e15)-(b.Due_Date||9e15)}).slice(0,12);$('attention-list').innerHTML=soon.length?'<div class="list">'+soon.map(function(t){var diff=Math.floor((day(t.Due_Date)-today)/864e5),label=diff<0?'<span class="badge red">En retard de '+Math.abs(diff)+' j</span>':diff<=7?'<span class="badge amber">Urgent · '+diff+' j</span>':'<span class="badge violet">À anticiper · '+diff+' j</span>';return '<div class="list-row"><div><div class="list-title">'+esc(t.Title)+'</div><div class="sub">'+esc(projectName(t.Project_Id))+'</div></div><span>'+fmtDate(t.Due_Date)+'</span>'+label+'<button class="btn small" onclick="openTask('+t.id+')">Ouvrir</button></div>'}).join('')+'</div>':'<div class="empty">Aucune tâche en retard ou attendue dans les 14 prochains jours.</div>';var standalone=doneY.filter(function(t){return !t.Project_Id}).length,projectsWithTime={};tasks.forEach(function(t){if(timeForTask(t.id,y)>0&&t.Project_Id)projectsWithTime[t.Project_Id]=true});$('activity-summary').innerHTML='<div class="list"><div class="list-row"><div class="list-title">Temps enregistré</div><strong>'+duration(sec)+'</strong></div><div class="list-row"><div class="list-title">Activités terminées</div><strong>'+doneY.length+'</strong></div><div class="list-row"><div class="list-title">Projets avec du temps suivi</div><strong>'+Object.keys(projectsWithTime).length+'</strong></div><div class="list-row"><div class="list-title">Activités autonomes terminées</div><strong>'+standalone+'</strong></div></div><button class="btn primary" style="margin-top:12px" onclick="openReport()">Ouvrir le bilan détaillé</button>'}
function metric(label,value,small,clickable){var action='openReport()',more='Ouvrir le bilan →';if(label==='Projets actifs'){action="openDashboardDetail('projects')";more='Voir les projets →'}else if(label==='Tâches ouvertes'){action="openDashboardDetail('tasks')";more='Voir les tâches →'}else if(label==='En retard'){action="openDashboardDetail('overdue')";more='Voir les retards →'}return '<div class="metric '+(clickable?'clickable':'')+'" '+(clickable?'onclick="'+action+'" tabindex="0" role="button"':'')+'><span>'+label+'</span><strong>'+value+'</strong><small>'+small+'</small>'+(clickable?'<small class="metric-more">'+more+'</small>':'')+'</div>'}

function openDashboardDetail(kind){var title='',subtitle='',html='',today=new Date(new Date().setHours(0,0,0,0));if(kind==='projects'){var ps=state.projects.filter(function(p){return (!state.project||String(p.id)===String(state.project))&&!isDone(p.Status)}).sort(function(a,b){return (a.Due_Date||9e15)-(b.Due_Date||9e15)});title='Projets actifs';subtitle=ps.length+' projet(s) en cours, en attente ou à préparer';html=ps.length?'<div class="detail-list">'+ps.map(function(p){return '<div class="detail-row"><div><div class="list-title">'+esc(p.Name)+'</div><div class="sub">'+esc(p.Type||'Projet')+' · Avancement : '+(p.Progress||0)+' %</div></div>'+badge(p.Status)+' '+badge(p.Priority,'priority')+'<button class="btn small" onclick="openDetailProject('+p.id+')">Ouvrir</button></div>'}).join('')+'</div>':'<div class="empty">Aucun projet actif.</div>'}else{var ts=state.tasks.filter(function(t){return (!state.project||String(t.Project_Id)===String(state.project))&&!isDone(t.Status)});if(kind==='overdue')ts=ts.filter(function(t){var d=day(t.Due_Date);return d&&d<today});ts.sort(function(a,b){return (a.Due_Date||9e15)-(b.Due_Date||9e15)});title=kind==='overdue'?'Tâches en retard':'Tâches ouvertes';subtitle=kind==='overdue'?ts.length+' tâche(s) dont l’échéance est dépassée':ts.length+' tâche(s) restant à organiser ou réaliser';html=ts.length?'<div class="detail-list">'+ts.map(function(t){var d=day(t.Due_Date),late=d&&d<today?Math.max(1,Math.ceil((today-d)/864e5)):0;return '<div class="detail-row '+(late?'overdue-row':'')+'"><div><div class="list-title">'+esc(t.Title)+'</div><div class="sub">'+esc(projectName(t.Project_Id))+' · '+taskTypeLabel(t.Type)+'</div></div>'+badge(t.Status)+(late?'<span class="badge red">'+late+' j de retard</span>':t.Due_Date?'<span>'+fmtDate(t.Due_Date)+'</span>':'<span class="badge violet">Sans échéance</span>')+'<button class="btn small" onclick="openDetailTask('+t.id+')">Ouvrir</button></div>'}).join('')+'</div>':'<div class="empty">'+(kind==='overdue'?'Aucune tâche en retard.':'Aucune tâche ouverte.')+'</div>'}$('dashboard-detail-title').textContent=title;$('dashboard-detail-subtitle').textContent=subtitle;$('dashboard-detail-body').innerHTML=html;showModal('dashboard-detail-modal')}
function openDetailProject(id){closeModal('dashboard-detail-modal');openProject(id)}
function openDetailTask(id){closeModal('dashboard-detail-modal');openTask(id)}
window.openDashboardDetail=openDashboardDetail;window.openDetailProject=openDetailProject;window.openDetailTask=openDetailTask;

function reportTasks(){return state.tasks.filter(function(t){return !state.project||String(t.Project_Id)===String(state.project)})}
function barList(items){var max=Math.max.apply(null,items.map(function(x){return x.value}).concat([1]));return items.length?'<div class="bar-list">'+items.map(function(x){return '<div class="bar-row"><span>'+esc(x.label)+'</span><div class="bar-track"><div class="bar-fill" style="width:'+(x.value/max*100)+'%"></div></div><strong>'+esc(x.display)+'</strong></div>'}).join('')+'</div>':'<div class="empty">Aucune donnée enregistrée.</div>'}
function renderReport(){if(!$('report-metrics'))return;var y=state.year,tasks=reportTasks(),done=tasks.filter(function(t){return t.Completed_At&&new Date(t.Completed_At*1000).getFullYear()===y}),seconds=tasks.reduce(function(s,t){return s+timeForTask(t.id,y)},0),projectTotals={},monthTotals=MONTHS.map(function(){return 0});state.time.forEach(function(e){if(!e.End_Time||new Date(e.End_Time*1000).getFullYear()!==y)return;var t=tasks.find(function(x){return String(x.id)===String(e.Task_Id)});if(!t)return;var name=projectName(t.Project_Id);projectTotals[name]=(projectTotals[name]||0)+(Number(e.Duration)||0);monthTotals[new Date(e.End_Time*1000).getMonth()]+=Number(e.Duration)||0});$('report-year').textContent=y;$('report-metrics').innerHTML=metric('Temps total',duration(seconds),'Chronométré ou saisi')+metric('Activités terminées',done.length,'Toutes catégories')+metric('Micro-tâches',done.filter(function(t){return t.Type==='micro'}).length,'Terminées')+metric('Tâches',done.filter(function(t){return !t.Type||t.Type==='task'}).length,'Terminées')+metric('Jalons',done.filter(function(t){return t.Type==='milestone'}).length,'Atteints');$('report-projects').innerHTML=barList(Object.keys(projectTotals).map(function(k){return {label:k,value:projectTotals[k],display:duration(projectTotals[k])}}).sort(function(a,b){return b.value-a.value}));$('report-months').innerHTML=barList(monthTotals.map(function(v,i){return {label:MONTHS[i],value:v,display:duration(v)}}));var types=[['Micro-tâches',done.filter(function(t){return t.Type==='micro'}).length],['Tâches',done.filter(function(t){return !t.Type||t.Type==='task'}).length],['Jalons',done.filter(function(t){return t.Type==='milestone'}).length]];$('report-types').innerHTML=barList(types.map(function(x){return {label:x[0],value:x[1],display:String(x[1])}}));var highlights=tasks.filter(function(t){return t.Review&&(timeForTask(t.id,y)>0||(t.Completed_At&&new Date(t.Completed_At*1000).getFullYear()===y))});$('report-highlights').innerHTML=highlights.length?'<div class="list">'+highlights.map(function(t){return '<div class="mention-row" onclick="openTask('+t.id+')"><strong>'+esc(t.Title)+'</strong><div class="sub">'+esc(projectName(t.Project_Id))+' · '+taskTypeLabel(t.Type)+'</div></div>'}).join('')+'</div>':'<div class="empty">Cochez « À mentionner en revue » sur les réalisations à valoriser.</div>';var detailed=tasks.filter(function(t){return timeForTask(t.id,y)>0||(t.Completed_At&&new Date(t.Completed_At*1000).getFullYear()===y)}).sort(function(a,b){return (b)+(Number(b.Completed_At)||0)-(Number(a.Completed_At)||0)});$('report-details').innerHTML=detailed.length?'<table class="report-table"><thead><tr><th>Activité</th><th>Projet</th><th>Type</th><th>Terminée</th><th>Temps</th></tr></thead><tbody>'+detailed.map(function(t){return '<tr><td>'+esc(t.Title)+'</td><td>'+esc(projectName(t.Project_Id))+'</td><td>'+taskTypeLabel(t.Type)+'</td><td>'+fmtDate(t.Completed_At)+'</td><td>'+duration(timeForTask(t.id,y))+'</td></tr>'}).join('')+'</tbody></table>':'<div class="empty">Aucune activité terminée ou chronométrée pour cette période.</div>'}
function openReport(){document.querySelector('[data-view="report"]').click()}
function printReport(){document.body.classList.add('print-report');window.print();setTimeout(function(){document.body.classList.remove('print-report')},500)}
window.openReport=openReport;window.printReport=printReport;

function renderKanban(){var ts=filteredTasks(),html='';TASK_STATUSES.filter(function(s){return state.showDone||!isDone(s[0])}).forEach(function(s){var list=ts.filter(function(t){return t.Status===s[0]});html+='<div class="lane" data-status="'+s[0]+'"><div class="lane-head"><span>'+s[1]+'</span><span class="badge">'+list.length+'</span></div><div class="lane-list">'+list.map(taskCard).join('')+'</div></div>'});$('kanban').innerHTML=html;document.querySelectorAll('.task-card').forEach(function(c){c.draggable=true;c.addEventListener('dragstart',function(){c.classList.add('dragging')});c.addEventListener('dragend',function(){c.classList.remove('dragging')})});document.querySelectorAll('.lane').forEach(function(l){l.addEventListener('dragover',function(e){e.preventDefault()});l.addEventListener('drop',async function(e){e.preventDefault();var c=document.querySelector('.task-card.dragging');if(!c)return;var t=state.tasks.find(function(x){return String(x.id)===c.dataset.id});var st=l.dataset.status,fields={Status:st,Updated_At:now()};if(st==='done'&&!t.Completed_At)fields.Completed_At=now();if(st!=='done')fields.Completed_At=null;await updateRecord(TABLES.tasks,t.id,fields);await loadData()})})}
function taskCard(t){var d=day(t.Due_Date),over=d&&d<new Date(new Date().setHours(0,0,0,0))&&!isDone(t.Status),tm=timeForTask(t.id),files=state.files.filter(function(x){return x.Parent_Type==='task'&&String(x.Parent_Id)===String(t.id)}).length,links=state.links.filter(function(x){return x.Parent_Type==='task'&&String(x.Parent_Id)===String(t.id)}).length,checks=state.checklist.filter(function(x){return String(x.Task_Id)===String(t.id)&&!x.Done}).length;return '<article class="task-card type-'+esc(t.Type||'task')+' '+(over?'overdue':'')+'" data-id="'+t.id+'" onclick="openTask('+t.id+')"><div class="type-label">'+taskTypeLabel(t.Type)+'</div><div>'+badge(t.Priority,'priority')+(t.Review?' <span class="badge blue">À signaler</span>':'')+'</div><h4>'+esc(t.Title)+'</h4><div class="sub">'+esc(projectName(t.Project_Id))+'</div><div class="card-meta">'+(t.Due_Date?'<span class="badge '+(over?'red':'')+'">'+fmtDate(t.Due_Date)+'</span>':'')+(tm?'<span class="badge blue">'+duration(tm)+'</span>':'')+(checks?'<span class="badge">☐ '+checks+'</span>':'')+(files?'<span class="badge">📎 '+files+'</span>':'')+(links?'<span class="badge">🔗 '+links+'</span>':'')+'</div></article>'}

function renderCalendar(){var base=state.calendar,y=base.getFullYear(),m=base.getMonth(),first=new Date(y,m,1),start=new Date(y,m,1-((first.getDay()+6)%7));$('cal-title').textContent=MONTHS[m]+' '+y;var html=['lun','mar','mer','jeu','ven','sam','dim'].map(function(x){return '<div class="cal-dow">'+x.toUpperCase()+'</div>'}).join('');for(var i=0;i<42;i++){var d=new Date(start);d.setDate(start.getDate()+i);var key=localDateKey(d),events=[];state.tasks.forEach(function(t){if(dateValue(t.Due_Date)===key&&(!state.project||String(t.Project_Id)===String(state.project))&&(state.showDone||!isDone(t.Status)))events.push('<span class="event '+(d<new Date().setHours(0,0,0,0)&&!isDone(t.Status)?'over':'')+'" onclick="openTask('+t.id+')">'+esc(t.Title)+'</span>')});state.projects.forEach(function(p){if(dateValue(p.Due_Date)===key&&(!state.project||String(p.id)===String(state.project))&&(state.showDone||!isDone(p.Status)))events.push('<span class="event project" onclick="openProject('+p.id+')">◆ '+esc(p.Name)+'</span>')});html+='<div class="cal-day '+(d.getMonth()!==m?'out':'')+'"><span class="cal-num">'+d.getDate()+'</span>'+events.join('')+'</div>'}$('calendar').innerHTML=html}

function renderGantt(){var y=state.year,start=new Date(y,0,1),end=new Date(y+1,0,1),span=end-start,ps=state.projects.filter(function(p){return (!state.project||String(p.id)===String(state.project))&&(state.showDone||!isDone(p.Status))});var months='<div class="gantt-row"><div class="gantt-name"><strong>Éléments</strong></div><div class="gantt-months">'+MONTHS.map(function(x){return '<span>'+x.slice(0,3)+'</span>'}).join('')+'</div></div>',rows='';ps.forEach(function(p){rows+=ganttRow(p.Name,p.Start_Date,p.Due_Date,start,span,false,p.id);state.tasks.filter(function(t){return String(t.Project_Id)===String(p.id)&&(state.showDone||!isDone(t.Status))}).forEach(function(t){rows+=ganttRow(t.Title,t.Start_Date||t.Due_Date,t.Due_Date||t.Start_Date,start,span,true,t.id)})});var orphan=state.tasks.filter(function(t){return !t.Project_Id&&(state.showDone||!isDone(t.Status))});orphan.forEach(function(t){rows+=ganttRow(t.Title,t.Start_Date||t.Due_Date,t.Due_Date||t.Start_Date,start,span,true,t.id)});$('gantt').innerHTML='<div class="gantt">'+months+(rows||'<div class="empty">Ajoutez des dates de début et de fin pour afficher le Gantt.</div>')+'</div>'}
function ganttRow(name,a,b,start,span,task,id){var da=day(a),db=day(b),bar='';if(da||db){da=da||db;db=db||da;var left=Math.max(0,Math.min(100,(da-start)/span*100)),right=Math.max(0,Math.min(100,(db-start)/span*100)),width=Math.max(.5,right-left+.3);bar='<span class="gantt-bar" style="left:'+left+'%;width:'+width+'%">'+esc(name)+'</span>'}return '<div class="gantt-row '+(task?'task':'')+'"><div class="gantt-name" onclick="'+(task?'openTask':'openProject')+'('+id+')">'+esc(name)+'</div><div class="gantt-track">'+bar+'</div></div>'}

function renderReview(){var ps=state.projects.filter(function(p){return p.Review&&(!state.project||String(p.id)===String(state.project))}),html=ps.map(function(p){var tasks=state.tasks.filter(function(t){return String(t.Project_Id)===String(p.id)&&!isDone(t.Status)}).sort(function(a,b){return Number(b.Review)-Number(a.Review)}),mentions=state.tasks.filter(function(t){return String(t.Project_Id)===String(p.id)&&t.Review}),sec=timeForProject(p.id,state.year);return '<article class="project-card"><div>'+badge(p.Status)+' '+badge(p.Priority,'priority')+'</div><h3>'+esc(p.Name)+'</h3><div class="sub">'+esc(p.Type||'Projet')+' · '+fmtDate(p.Start_Date)+' → '+fmtDate(p.Due_Date)+'</div><div class="progress"><i style="width:'+Math.max(0,Math.min(100,p.Progress||0))+'%"></i></div><div class="sub">Avancement : '+(p.Progress||0)+' % · '+tasks.length+' tâche(s) ouverte(s)</div>'+reviewBlock('Prochaine action',p.Next_Action)+reviewBlock('Points de vigilance',p.Risks)+reviewBlock('Décision attendue',p.Decision)+reviewMentions(mentions)+(tasks.length?'<div class="review-task-actions"><button class="btn small" onclick="toggleReviewTasks('+p.id+',this)">Voir les tâches ouvertes ('+tasks.length+')</button></div><div id="review-tasks-'+p.id+'" class="review-tasks hidden">'+tasks.map(reviewTaskRow).join('')+'</div>':'')+'<div class="review-footer"><span>'+duration(sec)+' suivies en '+state.year+'</span><button class="btn small" onclick="openProject('+p.id+')">Modifier</button></div></article>'}).join(''),standalone=state.tasks.filter(function(t){return !t.Project_Id&&t.Review});if(standalone.length)html+='<article class="project-card"><div>'+badge('active')+'</div><h3>Autres activités à signaler</h3><div class="sub">Tâches autonomes sélectionnées pour la revue</div>'+reviewMentions(standalone)+'</article>';$('review').innerHTML=html||'<div class="empty">Utilisez « Préparer la revue » pour sélectionner les projets à présenter.</div>'}
function reviewBlock(label,text){return text?'<div class="review-block"><b>'+label+'</b><p>'+esc(text)+'</p></div>':''}
function reviewMentions(tasks){return tasks.length?'<div class="review-mentions"><strong>Points à mentionner</strong>'+tasks.map(function(t){return '<div class="mention-row" onclick="openTask('+t.id+')"><strong>'+esc(t.Title)+'</strong><div class="sub">'+taskTypeLabel(t.Type)+' · '+statusLabel(t.Status)+' · '+fmtDate(t.Due_Date)+'</div></div>'}).join('')+'</div>':''}
function reviewTaskRow(t){return '<div class="review-task '+(t.Review?'review-important':'')+'" onclick="openTask('+t.id+')"><div class="review-task-head"><strong>'+esc(t.Title)+'</strong>'+badge(t.Status)+' '+badge(t.Priority,'priority')+'</div><div class="sub">'+taskTypeLabel(t.Type)+' · Échéance : '+fmtDate(t.Due_Date)+(t.Review?' · À mentionner en revue':'')+'</div>'+(t.Notes?'<div class="review-task-note">'+esc(t.Notes)+'</div>':'')+'</div>'}
function toggleReviewTasks(id,button){var box=$('review-tasks-'+id),opening=box.classList.contains('hidden');box.classList.toggle('hidden',!opening);button.textContent=opening?'Masquer les tâches':'Voir les tâches ouvertes ('+box.children.length+')'}
function renderReviewPicker(){var q=($('review-search').value||'').trim().toLowerCase(),ps=state.projects.slice().sort(function(a,b){return Number(b.Review)-Number(a.Review)||a.Name.localeCompare(b.Name)}).filter(function(p){return !q||String(p.Name).toLowerCase().includes(q)||String(p.Type||'').toLowerCase().includes(q)});$('review-picker').innerHTML=ps.length?ps.map(function(p){return '<label class="review-choice"><input type="checkbox" '+(p.Review?'checked':'')+' onchange="toggleProjectReview('+p.id+',this.checked)"><span><strong>'+esc(p.Name)+'</strong><br><small>'+esc(p.Type||'Projet')+' · '+esc(PROJECT_STATUSES[p.Status]||p.Status||'')+'</small></span></label>'}).join(''):'<div class="empty">Aucun projet trouvé.</div>'}
async function toggleProjectReview(id,checked){await updateRecord(TABLES.projects,id,{Review:checked,Updated_At:now()});var p=state.projects.find(function(x){return String(x.id)===String(id)});if(p)p.Review=checked;renderReview();renderDashboard()}

function renderRunning(){var e=activeEntry(),el=$('running-summary');if(!e){el.classList.add('hidden');return}var t=state.tasks.find(function(x){return String(x.id)===String(e.Task_Id)});el.classList.remove('hidden');el.textContent='Chronomètre : '+(t?t.Title:'Tâche')+' · '+duration(now()-e.Start_Time);if(!$('task-modal').classList.contains('hidden')&&String($('task-id').value)===String(e.Task_Id))renderTimer(e.Task_Id)}
function renderTimer(taskId){var e=activeEntry(),running=e&&String(e.Task_Id)===String(taskId),total=timeForTask(taskId)+(running?now()-e.Start_Time:0);$('timer-clock').textContent=duration(total);$('timer-toggle').textContent=running?'Arrêter':'Démarrer';$('timer-toggle').className='btn '+(running?'danger':'primary');$('time-list').innerHTML=state.time.filter(function(x){return String(x.Task_Id)===String(taskId)&&x.End_Time}).sort(function(a,b){return b.Start_Time-a.Start_Time}).slice(0,10).map(function(x){return '<div class="time-row"><span>'+new Date(x.Start_Time*1000).toLocaleDateString('fr-FR')+' · '+esc(x.Description||x.Source||'Session')+'</span><strong>'+duration(x.Duration)+'</strong></div>'}).join('')}

function relatedId(type){return Number($(type+'-id').value)}
function relatedItems(list,type,id){return list.filter(function(x){return x.Parent_Type===type&&String(x.Parent_Id)===String(id)})}
function formatFileSize(bytes){bytes=Number(bytes)||0;return bytes<1024?bytes+' o':bytes<1048576?Math.round(bytes/1024)+' Ko':(bytes/1048576).toFixed(1)+' Mo'}
function renderRelated(type,id){var box=$(type+'-related');box.classList.toggle('hidden',!id);if(!id)return;var files=relatedItems(state.files,type,id),links=relatedItems(state.links,type,id),journal=relatedItems(state.journal,type,id).sort(function(a,b){return (b.Created_At||0)-(a.Created_At||0)});$(type+'-files').innerHTML=files.length?files.map(function(x){return '<div class="related-item"><span>📎 <strong>'+esc(x.File_Name)+'</strong><br><small>'+formatFileSize(x.File_Size)+'</small></span>'+(canPreviewFile(x)?'<button type="button" class="btn small primary" onclick="viewFile('+x.id+')">Voir</button>':'')+'<button type="button" class="btn small" onclick="downloadFile('+x.id+')">Télécharger</button><button type="button" class="btn small danger" onclick="deleteRelated(\'files\','+x.id+',\''+type+'\')">×</button></div>'}).join(''):'<div class="sub">Aucun document.</div>';$(type+'-links').innerHTML=links.length?links.map(function(x){return '<div class="related-item"><a href="'+esc(x.URL)+'" target="_blank" rel="noopener noreferrer"><strong>🔗 '+esc(x.Label||x.URL)+'</strong></a><button type="button" class="btn small danger" onclick="deleteRelated(\'links\','+x.id+',\''+type+'\')">×</button></div>'}).join(''):'<div class="sub">Aucun lien.</div>';$(type+'-journal').innerHTML=journal.length?journal.map(function(x){return '<div class="related-item"><span><span class="journal-date">'+new Date(x.Created_At*1000).toLocaleString('fr-FR')+'</span><br>'+esc(x.Content)+'</span><button type="button" class="btn small danger" onclick="deleteRelated(\'journal\','+x.id+',\''+type+'\')">×</button></div>'}).join(''):'<div class="sub">Aucune note datée.</div>';if(type==='task'){var checks=state.checklist.filter(function(x){return String(x.Task_Id)===String(id)}).sort(function(a,b){return Number(a.Done)-Number(b.Done)||(a.Created_At||0)-(b.Created_At||0)});$('task-checklist').innerHTML=checks.length?checks.map(function(x){return '<div class="related-item check-item '+(x.Done?'done':'')+'"><input type="checkbox" '+(x.Done?'checked':'')+' onchange="toggleChecklist('+x.id+',this.checked)"><span class="check-text">'+esc(x.Text)+(x.Completed_At?'<br><small>Terminée le '+new Date(x.Completed_At*1000).toLocaleDateString('fr-FR')+'</small>':'')+'</span><button type="button" class="btn small danger" onclick="deleteRelated(\'checklist\','+x.id+',\'task\')">×</button></div>'}).join(''):'<div class="sub">Aucune mini-action.</div>'}}
async function addChecklistItem(){var id=relatedId('task'),text=$('task-check-text').value.trim();if(!id||!text)return;if(state.demo){toast('Disponible dans Grist.');return}await addRecord(TABLES.checklist,{Task_Id:id,Text:text,Done:false,Created_At:now(),Completed_At:null});$('task-check-text').value='';await loadData();renderRelated('task',id)}
async function toggleChecklist(id,done){if(state.demo)return;await updateRecord(TABLES.checklist,id,{Done:done,Completed_At:done?now():null});await loadData();renderRelated('task',relatedId('task'))}
async function addJournalEntry(type){var id=relatedId(type),field=$(type+'-journal-text'),content=field.value.trim();if(!id||!content)return;if(state.demo){toast('Disponible dans Grist.');return}await addRecord(TABLES.journal,{Parent_Type:type,Parent_Id:id,Content:content,Created_At:now()});field.value='';await loadData();renderRelated(type,id)}
async function addExternalLink(type){var id=relatedId(type),label=$(type+'-link-label').value.trim(),raw=$(type+'-link-url').value.trim(),url;try{url=new URL(raw);if(url.protocol!=='http:'&&url.protocol!=='https:')throw new Error()}catch(e){toast('Saisissez une adresse commençant par http:// ou https://');return}if(!id)return;if(state.demo){toast('Disponible dans Grist.');return}await addRecord(TABLES.links,{Parent_Type:type,Parent_Id:id,Label:label||url.hostname,URL:url.href,Notes:'',Created_At:now()});$(type+'-link-label').value='';$(type+'-link-url').value='';await loadData();renderRelated(type,id)}
function readFile(file){return new Promise(function(resolve,reject){var r=new FileReader();r.onerror=reject;r.onload=function(){resolve(r.result)};r.readAsDataURL(file)})}
async function uploadFiles(type,fileList){var id=relatedId(type),status=$(type+'-file-status');if(!id||!fileList||!fileList.length)return;if(state.demo){toast('Disponible dans Grist.');return}var added=0,skipped=[];for(var i=0;i<fileList.length;i++){var file=fileList[i];status.textContent='Ajout de '+file.name+'…';if(file.size>5*1024*1024){skipped.push(file.name);continue}try{await addRecord(TABLES.files,{Parent_Type:type,Parent_Id:id,File_Name:file.name,File_Type:file.type||'',File_Size:file.size||0,File_Data:await readFile(file),Created_At:now()});added++}catch(e){skipped.push(file.name)}}status.textContent='';await loadData();renderRelated(type,id);toast(added+' fichier(s) ajouté(s)'+(skipped.length?' · ignoré(s) : '+skipped.join(', '):''))}
function downloadFile(id){var f=state.files.find(function(x){return String(x.id)===String(id)});if(!f||!f.File_Data)return;var a=document.createElement('a');a.href=f.File_Data;a.download=f.File_Name||'document';document.body.appendChild(a);a.click();a.remove()}
function canPreviewFile(f){var type=String(f.File_Type||'').toLowerCase(),name=String(f.File_Name||'').toLowerCase();return /^(application\/pdf|image\/|text\/|audio\/|video\/)/.test(type)||/\.(pdf|png|jpe?g|gif|webp|svg|txt|csv|md|json|mp3|wav|mp4|webm)$/i.test(name)}
function viewFile(id){var f=state.files.find(function(x){return String(x.id)===String(id)});if(!f||!f.File_Data)return;var w=window.open('','_blank');if(!w){toast('Autorisez les fenêtres surgissantes pour visualiser le document.');return}try{var parts=String(f.File_Data).split(','),meta=parts[0]||'',binary=meta.includes(';base64')?atob(parts.slice(1).join(',')):decodeURIComponent(parts.slice(1).join(',')),bytes=new Uint8Array(binary.length);for(var i=0;i<binary.length;i++)bytes[i]=binary.charCodeAt(i);var blob=new Blob([bytes],{type:f.File_Type||'application/octet-stream'}),url=URL.createObjectURL(blob);w.location.href=url;setTimeout(function(){URL.revokeObjectURL(url)},60000)}catch(e){w.close();toast('Ce document ne peut pas être prévisualisé. Utilisez Télécharger.')}}
async function deleteRelated(kind,id,type){if(!confirm('Supprimer cet élément ?'))return;var table=kind==='files'?TABLES.files:kind==='links'?TABLES.links:kind==='journal'?TABLES.journal:TABLES.checklist;if(state.demo)return;await removeRecord(table,id);await loadData();renderRelated(type,relatedId(type))}
window.addChecklistItem=addChecklistItem;window.toggleChecklist=toggleChecklist;window.addJournalEntry=addJournalEntry;window.addExternalLink=addExternalLink;window.uploadFiles=uploadFiles;window.downloadFile=downloadFile;window.viewFile=viewFile;window.deleteRelated=deleteRelated;

function showModal(id){$(id).classList.remove('hidden')}function closeModal(id){$(id).classList.add('hidden')}
function openTask(id,quick){var t=state.tasks.find(function(x){return String(x.id)===String(id)});$('task-form').reset();$('task-id').value=t?t.id:'';$('task-modal-title').textContent=t?'Modifier la tâche':quick?'Tâche rapide':'Nouvelle tâche';$('task-title').value=t?t.Title:'';$('task-project').value=t&&t.Project_Id?t.Project_Id:state.project||'';$('task-type').value=t?t.Type||'task':quick?'micro':'task';$('task-status').value=t?t.Status||'todo':'todo';$('task-priority').value=t?t.Priority||'medium':'medium';$('task-start').value=t?dateValue(t.Start_Date):'';$('task-due').value=t?dateValue(t.Due_Date):'';$('task-estimate').value=t&&t.Estimated_Hours!=null?t.Estimated_Hours:'';$('task-review').checked=!!(t&&t.Review);$('task-notes').value=t?t.Notes||'':'';$('delete-task').classList.toggle('hidden',!t);$('timer-box').classList.toggle('hidden',!t);renderRelated('task',t&&t.id);showModal('task-modal');if(t)renderTimer(t.id);setTimeout(function(){$('task-title').focus()},10)}
function openProject(id){var p=state.projects.find(function(x){return String(x.id)===String(id)});$('project-form').reset();$('project-id').value=p?p.id:'';$('project-modal-title').textContent=p?'Modifier le projet':'Nouveau projet';$('project-name').value=p?p.Name:'';$('project-type').value=p?p.Type||'':'';$('project-status').value=p?p.Status||'active':'active';$('project-priority').value=p?p.Priority||'medium':'medium';$('project-progress').value=p?p.Progress||0:0;$('project-start').value=p?dateValue(p.Start_Date):'';$('project-due').value=p?dateValue(p.Due_Date):'';$('project-next').value=p?p.Next_Action||'':'';$('project-risks').value=p?p.Risks||'':'';$('project-decision').value=p?p.Decision||'':'';$('project-review').checked=!!(p&&p.Review);$('delete-project').classList.toggle('hidden',!p);renderRelated('project',p&&p.id);showModal('project-modal');setTimeout(function(){$('project-name').focus()},10)}
window.openTask=openTask;window.openProject=openProject;window.toggleProjectReview=toggleProjectReview;window.toggleReviewTasks=toggleReviewTasks;

async function saveTask(e){e.preventDefault();var id=$('task-id').value,st=$('task-status').value,old=state.tasks.find(function(x){return String(x.id)===String(id)}),fields={Title:$('task-title').value.trim(),Project_Id:$('task-project').value?Number($('task-project').value):null,Type:$('task-type').value,Status:st,Priority:$('task-priority').value,Start_Date:unix($('task-start').value),Due_Date:unix($('task-due').value),Notes:$('task-notes').value.trim(),Estimated_Hours:$('task-estimate').value===''?null:Number($('task-estimate').value),Review:$('task-review').checked,Updated_At:now()};if(!fields.Title)return;if(st==='done'&&(!old||!old.Completed_At))fields.Completed_At=now();else if(st!=='done')fields.Completed_At=null;if(id)await updateRecord(TABLES.tasks,id,fields);else{fields.Created_At=now();await addRecord(TABLES.tasks,fields)}closeModal('task-modal');await loadData();toast('Tâche enregistrée')}
async function saveProject(e){e.preventDefault();var id=$('project-id').value,fields={Name:$('project-name').value.trim(),Type:$('project-type').value.trim(),Status:$('project-status').value,Priority:$('project-priority').value,Progress:Number($('project-progress').value)||0,Start_Date:unix($('project-start').value),Due_Date:unix($('project-due').value),Next_Action:$('project-next').value.trim(),Risks:$('project-risks').value.trim(),Decision:$('project-decision').value.trim(),Review:$('project-review').checked,Updated_At:now()};if(!fields.Name)return;if(id)await updateRecord(TABLES.projects,id,fields);else{fields.Created_At=now();await addRecord(TABLES.projects,fields)}closeModal('project-modal');await loadData();toast('Projet enregistré')}
async function toggleTimer(){var taskId=Number($('task-id').value),e=activeEntry();if(e){if(String(e.Task_Id)!==String(taskId)){toast('Arrêtez d’abord le chronomètre déjà actif');return}var end=now();await updateRecord(TABLES.time,e.id,{End_Time:end,Duration:end-e.Start_Time});toast('Temps enregistré : '+duration(end-e.Start_Time))}else await addRecord(TABLES.time,{Task_Id:taskId,Start_Time:now(),End_Time:null,Duration:0,Description:'',Source:'timer',Created_At:now()});await loadData();renderTimer(taskId)}
async function manualTime(){var taskId=Number($('task-id').value),h=Number($('manual-hours').value)||0,m=Number($('manual-minutes').value)||0,sec=Math.round((h*60+m)*60);if(sec<=0){toast('Indiquez une durée');return}var end=now();await addRecord(TABLES.time,{Task_Id:taskId,Start_Time:end-sec,End_Time:end,Duration:sec,Description:'Saisie manuelle',Source:'manual',Created_At:end});$('manual-hours').value='';$('manual-minutes').value='';await loadData();renderTimer(taskId);toast('Temps ajouté')}

function bind(){document.querySelectorAll('.tab').forEach(function(b){b.addEventListener('click',function(){state.view=b.dataset.view;document.querySelectorAll('.tab').forEach(function(x){x.classList.toggle('active',x===b)});document.querySelectorAll('.view').forEach(function(x){x.classList.toggle('active',x.id==='view-'+state.view)})})});document.querySelectorAll('[data-close]').forEach(function(b){b.addEventListener('click',function(){closeModal(b.dataset.close)})});$('quick-task').onclick=function(){openTask(null,true)};$('new-project').onclick=function(){openProject()};$('import-projects').onclick=importExistingProjects;$('task-form').onsubmit=saveTask;$('project-form').onsubmit=saveProject;$('timer-toggle').onclick=toggleTimer;$('add-time').onclick=manualTime;$('project-filter').onchange=function(){state.project=this.value;refresh()};$('year-filter').onchange=function(){state.year=Number(this.value);refresh()};$('show-done').onchange=function(){state.showDone=this.checked;refresh()};$('cal-prev').onclick=function(){state.calendar=new Date(state.calendar.getFullYear(),state.calendar.getMonth()-1,1);renderCalendar()};$('cal-next').onclick=function(){state.calendar=new Date(state.calendar.getFullYear(),state.calendar.getMonth()+1,1);renderCalendar()};$('cal-today').onclick=function(){state.calendar=new Date(new Date().getFullYear(),new Date().getMonth(),1);renderCalendar()};$('delete-task').onclick=async function(){var id=$('task-id').value;if(!id||!confirm('Supprimer cette tâche et ses entrées de temps ?'))return;var entries=state.time.filter(function(x){return String(x.Task_Id)===String(id)});for(var i=0;i<entries.length;i++)await removeRecord(TABLES.time,entries[i].id);await removeRecord(TABLES.tasks,id);closeModal('task-modal');await loadData()};$('delete-project').onclick=async function(){var id=$('project-id').value;if(!id)return;var count=state.tasks.filter(function(x){return String(x.Project_Id)===String(id)}).length;if(!confirm('Supprimer ce projet ? Ses '+count+' tâche(s) deviendront autonomes.'))return;for(var i=0;i<state.tasks.length;i++)if(String(state.tasks[i].Project_Id)===String(id))await updateRecord(TABLES.tasks,state.tasks[i].id,{Project_Id:null});await removeRecord(TABLES.projects,id);closeModal('project-modal');await loadData()};document.querySelectorAll('.modal-bg').forEach(function(m){m.addEventListener('click',function(e){if(e.target===m)closeModal(m.id)})})}
function bindReviewManager(){$('manage-review').onclick=function(){$('review-search').value='';renderReviewPicker();showModal('review-modal')};$('review-search').oninput=renderReviewPicker}

async function init(){bind();bindReviewManager();$('task-status').innerHTML=TASK_STATUSES.map(function(s){return '<option value="'+s[0]+'">'+s[1]+'</option>'}).join('');state.demo=!(window.grist&&window.parent!==window);if(state.demo){$('demo-banner').classList.remove('hidden');demoLoad();refresh()}else{try{await grist.ready({requiredAccess:'full'});await ensureTables();await loadData();grist.onRecords(function(){loadData().catch(console.error)})}catch(e){console.error(e);toast('Connexion à Grist impossible : '+e.message)}}state.tick=setInterval(renderRunning,1000)}
init();
